actions.script:
import org.moqui.entity.EntityCondition

def zone = ec.user.timeZone.toZoneId()
def org = (crmOrganization.activeOrgId ?: '_NA_')
dashboardError = null
leadRows = []; opportunityRows = []; activityRows = []; myWork = []
stageRows = []; stageSummary = [:]; sourceSummary = [:]
leadStatusNames = [LeadNew:'New', LeadContacted:'Contacted', LeadQualified:'Qualified', LeadConverted:'Converted', LeadLost:'Lost']
leadCount = 0; qualifiedCount = 0; qualifiedRate = 0; openOpportunityCount = 0
pipelineValue = 0G; weightedValue = 0G; wonValue = 0G
activityCount = 0; followupDueCount = 0; unassignedLeads = 0; unattendedLeads = 0
closingSoon = 0; overdueRows = []
if (org && org != '_NA_') {
    try {
        def leadFind = ec.entity.find('zenith.erp.crm.LeadListView').condition('organizationPartyId', org)
        if (periodStart) leadFind.condition('createdDate', EntityCondition.GREATER_THAN_EQUAL_TO, periodStart)
        if (periodStart) leadFind.condition('createdDate', EntityCondition.LESS_THAN, periodEnd)
        leadRows = leadFind.orderBy('-createdDate').list()
        leadCount = leadRows.size()
        qualifiedCount = leadRows.count { it.statusId in ['LeadQualified','LeadConverted'] }
        qualifiedRate = leadCount ? (qualifiedCount * 100 / leadCount).intValue() : 0
        leadRows.each { row ->
            def source = row.sourceName ?: 'Unknown / not set'
            sourceSummary[source] = (sourceSummary[source] ?: 0) + 1
        }

        stageRows = ec.entity.find('mantle.sales.opportunity.SalesOpportunityStage').orderBy('sequenceNum').list()
        def allOpps = ec.entity.find('zenith.erp.crm.OpportunityListView').condition('organizationPartyId', org).list()
        opportunityRows = allOpps.findAll { row -> !periodStart || (row.estimatedCloseDate && row.estimatedCloseDate >= periodStart && row.estimatedCloseDate < periodEnd) }
        def totals = { rows, weighted = false ->
            rows.groupBy { it.currencyUomId ?: 'Unspecified' }.sort().collect { code, deals ->
                def amount = deals.sum { (it.estimatedAmount ?: 0G) * (weighted ? (it.estimatedProbability ?: 0G) : 1G) }
                code + ' ' + ec.l10n.format(amount, '#,##0.00')
            }.join(' / ') ?: '—'
        }
        def byStage = opportunityRows.groupBy { it.opportunityStageId }
        stageRows.each { stage ->
            def deals = byStage[stage.opportunityStageId] ?: []
            stageSummary[stage.opportunityStageId] = [count:deals.size(), value:totals(deals)]
        }
        def open = opportunityRows.findAll { !(it.opportunityStageId in ['SoClosedWon','SoClosedLost']) }
        openOpportunityCount = open.size()
        pipelineValue = totals(open)
        weightedValue = totals(open, true)
        wonValue = totals(allOpps.findAll { it.opportunityStageId == 'SoClosedWon' && (!periodStart || (it.wonDate && it.wonDate >= periodStart && it.wonDate < periodEnd)) })
        closingSoon = allOpps.count { !['SoClosedWon','SoClosedLost'].contains(it.opportunityStageId) &&
            it.estimatedCloseDate && it.estimatedCloseDate >= java.sql.Timestamp.from(crmToday.atStartOfDay(zone).toInstant()) &&
            it.estimatedCloseDate < java.sql.Timestamp.from(crmToday.plusDays(8).atStartOfDay(zone).toInstant()) }

        myWork = ec.entity.find('zenith.erp.crm.CrmActivity').condition('organizationPartyId',org)
            .condition('assignedToUserId',ec.user.userId).condition('statusId','Scheduled')
            .condition('dueDate',EntityCondition.LESS_THAN,periodEnd).orderBy('dueDate,activityId').limit(5).list()
        def activityFind = ec.entity.find('zenith.erp.crm.CrmActivity').condition('organizationPartyId', org)
        if (periodStart) activityFind.condition('activityDate', EntityCondition.GREATER_THAN_EQUAL_TO, periodStart)
        if (periodStart) activityFind.condition('activityDate', EntityCondition.LESS_THAN, periodEnd)
        activityCount = activityFind.count()
        activityRows = activityFind.orderBy('-activityDate').limit(6).list()
        def overdue = ec.entity.find('zenith.erp.crm.CrmActivity').condition('organizationPartyId',org)
            .condition('statusId','Scheduled').condition('dueDate',EntityCondition.LESS_THAN,ec.user.nowTimestamp)
        followupDueCount = overdue.count()
        overdueRows = overdue.orderBy('dueDate,activityId').limit(6).list()
        def scheduledLeadIds = ec.entity.find('zenith.erp.crm.CrmActivity').condition('organizationPartyId',org)
            .condition('statusId','Scheduled').selectField('leadId').distinct(true).list()*.leadId as Set
        def activeLeads = ec.entity.find('zenith.erp.crm.Lead').condition('organizationPartyId',org)
            .selectFields(['leadId','assignedToUserId','statusId']).list().findAll { !(it.statusId in ['LeadConverted','LeadLost']) }
        unassignedLeads = activeLeads.count { !it.assignedToUserId }
        unattendedLeads = activeLeads.count { !scheduledLeadIds.contains(it.leadId) }
    } catch (Exception e) {
        dashboardError = 'CRM data could not be loaded. Please retry or contact support.'
        leadRows = []; opportunityRows = []; activityRows = []; myWork = []
        stageRows = []; stageSummary = [:]; sourceSummary = [:]
        leadCount = 0; qualifiedCount = 0; qualifiedRate = 0; openOpportunityCount = 0
        pipelineValue = 0G; weightedValue = 0G; wonValue = 0G
        activityCount = 0; followupDueCount = 0; unassignedLeads = 0; unattendedLeads = 0; closingSoon = 0; overdueRows = []
    }
}
hasActiveOrg = org && org != '_NA_'
recentLeads = leadRows.take(6)
recentActivities = activityRows
sources = sourceSummary.collect { name, count -> [name:name, count:count] }
        .sort { a, b -> b.count <=> a.count }
def sourceColors = ['#078996', '#4a94f2', '#3ac493', '#ffbd3e', '#ff8656', '#fa6672']
def sourceOffset = 0G
sourceGradient = sources.withIndex().collect { source, index ->
    def start = sourceOffset
    sourceOffset = index == sources.size() - 1 ? 100G : sourceOffset + (source.count * 100G / leadCount)
    "${sourceColors[index % sourceColors.size()]} ${String.format(java.util.Locale.US, '%.2f', start.doubleValue())}% ${String.format(java.util.Locale.US, '%.2f', sourceOffset.doubleValue())}%"
}.join(', ')
maxStageCount = stageSummary.values().collect { it.count }.max() ?: 0
stageRows.each { stage ->
    def bucket = stageSummary[stage.opportunityStageId]
    bucket.barLevel = maxStageCount ? Math.max(1, Math.round(bucket.count * 10.0 / maxStageCount)) : 0
}
